import{_ as o}from"./chunks/image12.BRgDBKom.js";import{_ as a,o as i,c as r,am as t,j as n}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/video1.DuwJk5OK.mp4",l="/projects/AiMechaM1/en/advanced-kit/assets/image2.pIeVa-UE.png",c="/projects/AiMechaM1/en/advanced-kit/assets/image3.DYkGd6Tu.png",d="/projects/AiMechaM1/en/advanced-kit/assets/image4.BqbmamZB.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image5.Bj0GLkOu.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image6.rgrtHqxi.png",k=JSON.parse('{"title":"3.31 Lesson 31: Complex Environment Perception and Decision-Making","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.31 Lesson 31 Complex Environment Perception and Decision-Making.md","filePath":"docs/3. Course materials/3.31 Lesson 31 Complex Environment Perception and Decision-Making.md"}'),g={name:"docs/3. Course materials/3.31 Lesson 31 Complex Environment Perception and Decision-Making.md"};function h(u,e,b,f,v,y){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_3-31-lesson-31-complex-environment-perception-and-decision-making" tabindex="-1">3.31 Lesson 31: Complex Environment Perception and Decision-Making <a class="header-anchor" href="#_3-31-lesson-31-complex-environment-perception-and-decision-making" aria-label="Permalink to &quot;3.31 Lesson 31: Complex Environment Perception and Decision-Making&quot;">​</a></h1><h2 id="_3-31-1-lesson-introduction" tabindex="-1">3.31.1 Lesson Introduction <a class="header-anchor" href="#_3-31-1-lesson-introduction" aria-label="Permalink to &quot;3.31.1 Lesson Introduction&quot;">​</a></h2><p>This lesson formally introduces embodied intelligence, exploring the closed loop of perception, decision-making, and control as intelligent agents interact with the physical world. Starting from the premise that a disembodied &quot;large model cannot take physical action&quot;, the curriculum covers the three core characteristics of perception, decision-making, and control, contrasting virtual symbol processing in traditional AI with real-world physical experience gained through embodied interaction. Key applications across autonomous driving, service robots, and industrial robotic arms are examined. Practical exercises utilize ultrasonic obstacle avoidance to demonstrate acoustic ranging principles for autonomous navigation, integrating large model interfaces to define obstacle avoidance strategies via natural language. Completing the leap from conversational control to embodied autonomous intelligence lays a solid foundation for multi-module collaborative applications.</p><h2 id="_3-31-2-learning-objectives" tabindex="-1">3.31.2 Learning Objectives <a class="header-anchor" href="#_3-31-2-learning-objectives" aria-label="Permalink to &quot;3.31.2 Learning Objectives&quot;">​</a></h2><ol><li><p>Understand the core definition and three primary characteristics of embodied intelligence. Master the fundamental differences between traditional AI and embodied intelligence. Learn how embodied intelligence is applied in autonomous driving, service robots, and industrial automation.</p></li><li><p>Program cyclic distance reading using an ultrasonic sensor. Set safety distance thresholds and write conditional statements for obstacle avoidance. Integrate large model interfaces to implement obstacle avoidance strategies defined via natural language.</p></li><li><p>Establish a systems mindset centered on the perception, decision-making, and control closed loop. Cultivate an embodied cognition perspective to understand the relationship between a physical body and intelligence, and enhance logical design skills for autonomous decision-making systems.</p></li><li><p>Connect real-world products such as autonomous vehicles, robotic vacuum cleaners, delivery robots, and industrial collaborative robots to understand industry trends in embodied intelligence.</p></li></ol><h2 id="_3-31-3-preparation" tabindex="-1">3.31.3 Preparation <a class="header-anchor" href="#_3-31-3-preparation" aria-label="Permalink to &quot;3.31.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li>AiMecha M1 Mecanum-Wheel Car Advanced Kit</li><li>Type-C data cable</li><li>Computer × 1</li><li>Remote controller</li></ul><p><strong>Software Preparation</strong>:</p><ul><li>WonderLab graphical programming software</li></ul><p><strong>Embodied Intelligence Core Concepts</strong>:</p><ul><li><p><strong>Definition</strong>: An intelligent agent interacts with the physical environment in real time through its physical &quot;body&quot;, continuously learning and adapting within a closed loop of perception, decision-making, and control. Because the physical body is an integral part of intelligence, intelligence does not reside solely in the &quot;brain&quot; but also depends on mechanical structure, sensor accuracy, and actuator performance. In short, an embodied agent possesses a body, perceives the environment, takes physical action, and learns from interaction.</p></li><li><p><strong>Three Core Characteristics</strong>:</p><ul><li><p>Perception: Acquiring environmental data through sensors, including ultrasonic sensors, cameras, infrared sensors, and LiDAR.</p></li><li><p>Decision-Making: Selecting appropriate actions based on perceptual data combined with preset rules or AI models.</p></li><li><p>Control: Translating decisions into concrete physical actions such as motor speeds, servo angles, and motion trajectories.</p></li></ul></li></ul><p><strong>Traditional AI vs. Embodied Intelligence Comparison</strong>:</p><ul><li><p><strong>Traditional AI</strong>: Operates &quot;virtually&quot;, processing symbols and text in digital environments without physical constraints or real-world sensory experience, like learning from books.</p></li><li><p><strong>Embodied Intelligence</strong>: Accounts for the physical world&#39;s constraints and gains real-world experience through direct environmental interaction, like learning through real-world experience.</p></li></ul><p><strong>Three Application Scenarios</strong>:</p><ul><li><p><strong>Autonomous Driving</strong>: Vehicles perceive road conditions via cameras and LiDAR, making real-time decisions to accelerate, brake, and steer in physical traffic. Because safety-critical decisions cannot wait for cloud round-trips, processing must occur end-to-end in real time.</p></li><li><p><strong>Service Robots</strong>: Restaurant delivery robots perceive hallways, tables, and pedestrians to navigate autonomously to target tables, while hotel service robots autonomously ride elevators to deliver items.</p></li><li><p><strong>Industrial Robotic Arms</strong>: Robotic arms adjust grasping postures based on visually detected part positions to complete assembly tasks, adapting dynamically to minor variations on the production line.</p></li></ul><p><strong>Ultrasonic Ranging Principle</strong>:</p><ul><li><p>Principle: Echolocation: an ultrasonic transmitter emits high-frequency acoustic waves that reflect off obstacles, and a receiver detects the returning echoes.</p></li><li><p>Formula: Distance = speed of sound × elapsed time divided by 2, where dividing by 2 accounts for the round-trip travel of the acoustic wave.</p></li><li><p>Speed of Sound: Approximately 340 meters per second in air.</p></li><li><p>Characteristics: Features low cost, simple operation, and immunity to lighting variations, but has limited precision, reduced effectiveness on soft sound-absorbing materials, and angular detection limits.</p></li></ul><p><strong>Wiring Instructions</strong>:</p><ul><li><p>Connect the K230 screen module to <strong>port A</strong> of the controller.</p></li><li><p>Connect the glowing ultrasonic sensor to <strong>port K</strong>.</p></li></ul><p><strong>MCP Ultrasonic Tool</strong>:</p><ul><li><p>Tool Name: Glowing Ultrasonic Distance Measurement.</p></li><li><p>Return Value: Obstacle distance measured in centimeters.</p></li><li><p>Invocation Method: Based on natural language instructions, the large model automatically invokes the ultrasonic ranging tool to obtain distance data and make movement decisions.</p></li></ul><h2 id="_3-31-4-practical-implementation" tabindex="-1">3.31.4 Practical Implementation <a class="header-anchor" href="#_3-31-4-practical-implementation" aria-label="Permalink to &quot;3.31.4 Practical Implementation&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This project builds an ultrasonic autonomous obstacle avoidance system under the embodied intelligence framework, centered around an edge-side perception, decision-making, and control closed loop. Real-time ultrasonic ranging supplies continuous environmental distance data. The decision-making layer features a dual-tier architecture: edge-side conditional logic sets a 10 cm threshold, while the advanced mode uses the large model to parse natural language strategies and invoke MCP tools to generate motion commands. The control layer drives the four Mecanum wheel motors to move forward or translate left for obstacle avoidance, forming a continuous closed loop of ranging, evaluation, decision-making, and execution. Operating autonomously without remote control demonstrates how intelligence emerges from physical interaction with the environment, while the large model lowers the barrier to rule definition by allowing complex strategies to be specified in a single spoken sentence. This system serves as a miniature prototype of embodied intelligence applications such as autonomous driving.</p>',25),n("p",null,[n("video",{controls:"",playsinline:"",preload:"metadata",src:s})],-1),t('<p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Ultrasonic tool</td><td style="text-align:center;"><img loading="lazy" height="36" width="579" src="'+l+'" class="common_img" style="width:100px;aspect-ratio:579 / 36;"></td><td style="text-align:left;">Evaluates whether the large model has invoked the ultrasonic distance measurement tool.</td></tr><tr><td style="text-align:center;">Distance feedback</td><td style="text-align:center;"><img loading="lazy" height="52" width="605" src="'+c+'" class="common_img" style="width:100px;aspect-ratio:605 / 52;"></td><td style="text-align:left;">Sends the measured obstacle distance value along with its unit back to the large model.</td></tr><tr><td style="text-align:center;">Motor control</td><td style="text-align:center;"><img loading="lazy" height="38" width="568" src="'+d+'" class="common_img" style="width:100px;aspect-ratio:568 / 38;"></td><td style="text-align:left;">Independently sets the rotational speeds of the four wheel motors to execute forward movement, lateral translation, or steering for obstacle avoidance.</td></tr><tr><td style="text-align:center;">Movement control</td><td style="text-align:center;"><img loading="lazy" height="60" width="544" src="'+p+'" class="common_img" style="width:100px;aspect-ratio:544 / 60;"></td><td style="text-align:left;">Precisely controls the movement direction and travel distance of the car to execute avoidance maneuvers.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task: Large Model-Driven Ultrasonic Autonomous Obstacle Avoidance System</strong></p><ul><li><p>Initialization settings: Upon startup, wait 6 seconds and play note B5 for a 1/8 beat as the startup prompt tone. Initialize port A, configure the Wi-Fi SSID as Hiwonder and the password as hiwonder2026, load the default MCP configuration, set the operating mode to online large model, initialize the linkage robotic arm, and play note B6 for a 1/8 beat as the readiness prompt tone.</p></li><li><p>Main loop structure: Start detection execution, and repeatedly update and save result data.</p></li><li><p>Result retrieval branch: If <code>Does result exist?</code> returns true, store the retrieved recognition result in the AIresult variable.</p></li><li><p>Motor speed branch: If AIresult contains the default MCP tool name for motor speed, set the front-left, rear-left, front-right, and rear-right wheel speeds of the Mecanum-wheel car to the respective motor speed parameters extracted from AIresult, and send a response result with dictionary key <code>result</code> and value <code>ok</code>.</p></li><li><p>Movement distance branch: If AIresult contains the default MCP tool name for movement distance, command the Mecanum-wheel car to translate at the rotational speed in rpm, toward the directional angle in degrees, and for the distance in centimeters extracted from AIresult, then send the response result <code>ok</code>.</p></li><li><p>Ultrasonic ranging branch: If AIresult contains the default MCP tool name for glowing ultrasonic distance measurement, send a response result with dictionary key <code>result</code> and a value concatenating the obstacle distance in centimeters measured by the ultrasonic sensor with the unit string <code>cm</code>, feeding the real-time distance back to the large model.</p></li><li><p>Obstacle avoidance strategy phrase: Speak the command to Hiwonder: &quot;Evaluate the distance to the obstacle ahead. If the distance is less than 10 cm, turn the car left. If the distance is greater than 10 cm, drive straight. Repeat this evaluation continuously.&quot;</p></li><li><p>Workflow: After receiving the spoken obstacle avoidance strategy, the large model continuously invokes the ultrasonic ranging tool to obtain distance readings, determines whether to translate left or continue driving straight based on the returned value, and invokes the motor speed or movement distance tool to drive the car—forming a continuous perception, decision-making, and action closed loop.</p></li></ul><img loading="lazy" height="575" width="1481" src="'+m+'" class="common_img" style="width:800px;aspect-ratio:1481 / 575;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1qESIR7n_mxv3oQTrZhNbBTnPKVOk-yT4?usp=sharing" target="_blank" rel="noreferrer">Program Files/Environmental Perception and Judgment</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and plug the Type-C data cable into the data port located above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button on the top toolbar of the software and select the COM port corresponding to CH340 from the dropdown list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to compile and download the program to the mecha controller.</p></li></ul><img loading="lazy" height="508" width="960" src="'+o+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-31-5-expansion-and-advancement" tabindex="-1">3.31.5 Expansion and Advancement <a class="header-anchor" href="#_3-31-5-expansion-and-advancement" aria-label="Permalink to &quot;3.31.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Expansion Project 1: Multi-Sensor Fusion Obstacle Avoidance System</strong></p><p>Beyond the ultrasonic sensor, integrate multiple perception modalities, such as large vision model recognition, a 6-channel line follower, and infrared sensors, to design a comprehensive intelligent obstacle avoidance system. For example, use vision to classify obstacles as pedestrians, objects, or walls and apply tailored avoidance strategies, while the line follower maintains path tracking and the ultrasonic sensor handles sudden close-range obstacles. Explore how multi-sensor fusion enhances environmental perception in embodied intelligence and understand why real-world robots rely on complementary sensor suites.</p><p><strong>Expansion Project 2: Intelligent Patrol Robot</strong></p><p>Design an autonomous patrol task where the car roams a designated area, automatically bypassing obstacles to maintain uninterrupted patrolling. Add an alarm function that activates the buzzer and flashes the RGB LEDs upon detecting specific targets such as human faces or objects of a designated color. Simulate the operating mode of a security patrol robot to explore embodied intelligence applications in security inspection and master the system design principles required for continuous autonomous mobile robot operation.</p><h2 id="_3-31-6-q-a" tabindex="-1">3.31.6 Q&amp;A <a class="header-anchor" href="#_3-31-6-q-a" aria-label="Permalink to &quot;3.31.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is embodied intelligence?</strong></p><p><strong>Answer</strong>: Embodied intelligence is a major frontier in artificial intelligence founded on the core principle that <strong>intelligence does not exist in isolation inside a brain, but emerges and manifests through real-time interaction between a physical body and its environment</strong>.</p><p><strong>Q2: How does an ultrasonic sensor measure distance?</strong></p><p><strong>Answer</strong>: An ultrasonic sensor measures distance using <strong>echolocation</strong>, the exact same physical principle used by bats flying at night and dolphins navigating underwater.</p><h2 id="_3-31-7-technical-support-and-discussion" tabindex="-1">3.31.7 Technical Support and Discussion <a class="header-anchor" href="#_3-31-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.31.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',22)])])}const x=a(g,[["render",h]]);export{k as __pageData,x as default};
